#!/bin/bash
set -e

echo "=================================================="
echo " Fix: remove duplicate Near row from OPD Case Sheet"
echo " Refraction table (only Dist. + NEAR ADD should show)"
echo "=================================================="
echo ""
echo "The version currently live on GitHub main (commit"
echo "12e87b3) still has THREE rows: Dist., Near, NEAR ADD."
echo "That Near row was a mistake -- it duplicates/contradicts"
echo "NEAR ADD. This patches it down to just Dist. and NEAR"
echo "ADD, exactly matching the Spectacle Prescription"
echo "printout, with near visual acuity folded into NEAR"
echo "ADD's own VISION column."
echo ""

TARGET="app/print-templates/actions.js"

if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi

echo "Backing up current file to $TARGET.bak ..."
cp "$TARGET" "$TARGET.bak"

echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"

echo ""
echo "Verifying JS syntax ..."
node --check "$TARGET" && echo "  Syntax OK"

echo ""
echo "Done. Review the diff with:"
echo "  git diff $TARGET"
